/bin/bash -lc "python3 -m py_compile /workspace/openai_client.py && python3 - <<'PY'
import json
from unittest.mock import patch
import openai_client

class FakeResponse:
    headers = {\"x-request-id\": \"req_test\"}
    def __enter__(self): return self
    def __exit__(self, *args): pass
    def read(self):
        return json.dumps({
            \"id\": \"resp_test\",
            \"model\": \"test-model\",
            \"output\": [{\"content\": [{\"type\": \"output_text\", \"text\": \"private answer\"}]}],
        }).encode()

with patch(\"openai_client.urlopen\", return_value=FakeResponse()) as mocked:
    result = openai_client.OpenAIClient(\"secret\").create_response(\"private prompt\", model=\"test-model\")
    assert result.text == \"private answer\"
    request = mocked.call_args.args[0]
    sent = json.loads(request.data)
    assert sent == {\"model\": \"test-model\", \"input\": \"private prompt\", \"store\": False}
    assert request.get_header(\"Authorization\") == \"Bearer secret\"

try:
    openai_client.OpenAIClient(\"secret\", api_url=\"http://example.com/v1/responses\")
except ValueError:
    pass
else:
    raise AssertionError(\"insecure URL accepted\")
print(\"compile and mocked request tests passed\")
PY"

